<article class="product-card"><a class="product-picture" href="/product/<?= e($p['slug']) ?>"><img src="<?= e(image_url(product_images($p)[0]??'/assets/favicon.svg')) ?>" alt="<?= e($p['name']) ?>" loading="lazy" width="600" height="750"><?php if(product_price($p)<(int)$p['price']): ?><span class="badge">A lovely little offer</span><?php elseif(!(int)$p['stock']): ?><span class="badge">Sold out</span><?php endif ?></a><div class="product-caption"><div><span class="eyebrow"><?= e($p['category_name']??'Accessories') ?></span><h3><a href="/product/<?= e($p['slug']) ?>"><?= e($p['name']) ?></a></h3><span><?= money(product_price($p)) ?></span><?php if(product_price($p)<(int)$p['price']): ?><del><?= money((int)$p['price']) ?></del><?php endif ?><?php if(offer_product_conditions($p)): ?><small class="offer-terms">Basket offers available</small><?php endif ?></div><button class="add-round" data-add="<?= e($p['id']) ?>" aria-label="Add <?= e($p['name']) ?> to your bag" <?= !$p['stock']?'disabled':'' ?>>+</button></div></article>
